# ── App icon (embedded ICO — all sizes 16/32/48/64/128/256 px) ────────────────
_ICON_B64 = ""

def _get_icon() -> "QIcon":
    """
    Decode the embedded ICO and return a QIcon usable by Qt.
    Loads all sizes directly from bytes into QPixmap — no temp file,
    no disk I/O, no lazy-read timing issue.
    """
    from PyQt6.QtGui import QIcon, QPixmap
    from PyQt6.QtCore import QByteArray
    raw   = base64.b64decode(_ICON_B64)
    icon  = QIcon()
    # Load each size from the ICO data — Qt parses the ICO format natively
    ba    = QByteArray(raw)
    pm    = QPixmap()
    pm.loadFromData(ba, "ICO")
    if not pm.isNull():
        icon.addPixmap(pm)
    # Also try loading individual sizes explicitly for better taskbar rendering
    for sz in (16, 32, 48, 256):
        pm2 = QPixmap()
        pm2.loadFromData(ba, "ICO")
        if not pm2.isNull():
            scaled = pm2.scaled(sz, sz,
                                 __import__('PyQt6.QtCore', fromlist=['Qt']).Qt.AspectRatioMode.KeepAspectRatio,
                                 __import__('PyQt6.QtCore', fromlist=['Qt']).Qt.TransformationMode.SmoothTransformation)
            icon.addPixmap(scaled)
    return icon

