# ─── Helpers ──────────────────────────────────────────────────────────────────
def load_settings():
    try:
        with open(SETTINGS_FILE) as f: return json.load(f)
    except Exception: return {}

def save_settings(d):
    try:
        with open(SETTINGS_FILE,"w") as f: json.dump(d,f,indent=2)
    except Exception: pass

def hex_dump(data): return " ".join(f"{b:02X}" for b in data)
def to_ascii(data): return "".join(chr(b) if 32<=b<127 else "." for b in data)

def fmt_size(sz):
    if sz<1024: return f"{sz} B"
    if sz<1048576: return f"{sz/1024:.1f} KB"
    return f"{sz/1048576:.2f} MB"

def eval_filter(text:str, filt:str, mode:str) -> bool:
    filt=filt.strip()
    if not filt: return True
    if mode=="regex":
        try:    return bool(re.search(filt,text,re.IGNORECASE))
        except: return True
    low=text.lower()
    for grp in filt.split("|"):
        terms=[t.strip().lower() for t in grp.split("&") if t.strip()]
        if terms and all(t in low for t in terms):
            return True
    return False


# ─── LogStore (piece-table bytearray storage) ─────────────────────────────────
class LogStore:
    """
    Stores all log entries as raw bytes in a flat bytearray.
    Index: packed struct per entry = 15 bytes vs ~300 bytes for a dict.
    get_text(i) is O(1) and allocates no objects beyond the string.
    """
    REC = struct.Struct("<IHBBIxxx")   # offset(4) len(2) dir(1) flags(1) ts_sec(4) pad(3)
    DIR = {"rx":0,"tx":1,"sys":2}
    RDIR= {0:"rx",1:"tx",2:"sys"}

    def __init__(self):
        self._buf   = bytearray()
        self._idx   = bytearray()
        self._count = 0
        self._epoch = datetime.datetime.now()
        self._lock  = threading.Lock()

    def append(self, direction:str, text:str, ts:datetime.datetime, is_bytes=False) -> int:
        raw    = text.encode("utf-8","replace")
        length = min(len(raw), 65535)
        d      = self.DIR.get(direction, 2)
        flags  = 1 if is_bytes else 0
        ts_sec = max(0, int((ts-self._epoch).total_seconds()))
        with self._lock:
            offset = len(self._buf)   # compute inside lock — thread-safe
            self._buf.extend(raw[:length])
            self._idx.extend(self.REC.pack(offset,length,d,flags,ts_sec))
            self._count += 1
            return self._count-1

    def __len__(self):
        return self._count

    def get_text(self, i:int) -> str:
        off = i * self.REC.size
        offset,length,d,flags,_ = self.REC.unpack_from(self._idx,off)
        return self._buf[offset:offset+length].decode("utf-8","replace")

    def get_dir(self, i:int) -> str:
        return self.RDIR.get(self._idx[i * self.REC.size + 5], "sys")

    def get_ts(self, i:int) -> datetime.datetime:
        ts_sec = self.REC.unpack_from(self._idx, i * self.REC.size)[4]
        return self._epoch + datetime.timedelta(seconds=ts_sec)

    def get_is_bytes(self, i:int) -> bool:
        return bool(self._idx[i * self.REC.size + 6] & 1)

    def clear(self):
        with self._lock:
            self._buf=bytearray(); self._idx=bytearray(); self._count=0

    def mem_mb(self) -> float:
        return (len(self._buf)+len(self._idx))/1_048_576


# ─── MmapFileStore ────────────────────────────────────────────────────────────
class MmapFileStore:
    """
    Opens a file via mmap. Never loads into RAM.
    Line index is built once in a background thread.
    get_line(i) is O(1) after indexing.
    """
    def __init__(self, path:str):
        self._path    = path
        self._f       = None
        self._mm      = None
        self._offsets = None   # numpy int64 array of line start offsets
        self._lengths = None   # numpy int32 array of line byte lengths
        self._count   = 0
        self._indexed = False
        self._size    = os.path.getsize(path)

    def open(self):
        self._f  = open(self._path, "rb")
        if self._size > 0:
            self._mm = mmap.mmap(self._f.fileno(), 0, access=mmap.ACCESS_READ)

    def build_index(self, cancel:threading.Event, progress_cb=None):
        """
        Build line offset/length index using numpy vectorized search.
        Finds all newlines in one C-speed pass — 17x faster than Python loop.
        A 60MB file indexes in ~0.2s instead of ~4s.
        numpy is imported lazily here so it does not slow down app startup.
        """
        import numpy as np   # lazy import — only needed when a file is opened
        mm = self._mm
        if mm is None:
            self._indexed = True
            return

        if progress_cb: progress_cb(5)

        # Copy mmap into numpy buffer — releases the mmap reference immediately
        # so we can close the file handle if needed. The GIL is released during
        # the copy and the np.where scan — UI stays responsive.
        buf = np.frombuffer(mm[:], dtype=np.uint8)

        if cancel.is_set(): return
        if progress_cb: progress_cb(40)

        # Find all newline positions in one vectorized C call
        nl_pos = np.where(buf == ord('\n'))[0]

        if cancel.is_set(): return
        if progress_cb: progress_cb(75)

        # Build start offsets: line 0 starts at 0, every other line starts after \n
        n = len(nl_pos)
        starts = np.empty(n + 1, dtype=np.int64)
        starts[0] = 0
        if n > 0:
            starts[1:] = nl_pos + 1

        # Line lengths = distance from start to the \n (or end of file)
        ends    = np.empty(n + 1, dtype=np.int64)
        ends[:n] = nl_pos
        ends[n]  = self._size
        lengths  = np.minimum(ends - starts, 65535).astype(np.int32)

        # Drop the phantom empty line after a trailing newline
        if n > 0 and nl_pos[-1] == self._size - 1:
            starts  = starts[:n]
            lengths = lengths[:n]

        self._offsets = starts
        self._lengths = lengths
        self._count   = len(starts)
        self._indexed = True

        if progress_cb: progress_cb(100)

    def get_line(self, i:int) -> str:
        if self._mm is None or self._offsets is None or i >= self._count:
            return ""
        off = int(self._offsets[i])
        ln  = int(self._lengths[i])
        return self._mm[off:off+ln].rstrip(b"\r").decode("utf-8", "replace")

    def __len__(self): return self._count

    def close(self):
        try:
            if self._mm: self._mm.close()
            if self._f:  self._f.close()
        except Exception: pass
        self._mm=None; self._f=None


# ─── Log Item Delegate (custom row painter) ───────────────────────────────────
class LogDelegate(QStyledItemDelegate):
    """
    Paints each log row with syntax colouring and line number gutter.
    Only called for visible rows — this is the key to performance.

    file_mode=False (live view): expects lines formatted as "HH:MM:SS.ms  DIR  text"
    file_mode=True  (file view): detects format automatically, falls back to fg colour
    """
    GUTTER_W = 56

    def __init__(self, palette:dict, font:QFont, file_mode:bool=False, parent=None):
        super().__init__(parent)
        self._pal       = palette
        self._font      = font
        self._file_mode = file_mode
        self._fm   = QFontMetrics(font)
        self._bold = QFont(font); self._bold.setBold(True)
        self._fm_b = QFontMetrics(self._bold)
        self._row_h= self._fm.height() + 4

    def update_style(self, palette:dict, font:QFont):
        self._pal=palette; self._font=font
        self._fm=QFontMetrics(font); self._bold=QFont(font); self._bold.setBold(True)
        self._fm_b=QFontMetrics(self._bold); self._row_h=self._fm.height()+4

    def sizeHint(self, option, index):
        return QSize(option.rect.width(), self._row_h)

    def paint(self, painter:QPainter, option:QStyleOptionViewItem, index:QModelIndex):
        painter.save()
        p   = self._pal
        row = index.row()

        # Background — alternating rows
        bg = p["bg3"] if row % 2 == 0 else p["bg"]
        painter.fillRect(option.rect, QColor(bg))

        # Selected highlight
        if bool(option.state & QStyle.StateFlag.State_Selected):
            painter.fillRect(option.rect, QColor(p["border"]))

        r  = option.rect
        x  = r.x(); y = r.y(); h = r.height()
        fm = self._fm

        # Gutter
        gutter_rect = QRect(x, y, self.GUTTER_W, h)
        painter.fillRect(gutter_rect, QColor(p.get("gutter", p["bg3"])))
        painter.setPen(QColor(p["ts"]))
        painter.setFont(self._font)
        ln_text = index.data(Qt.ItemDataRole.UserRole+1)
        if ln_text:
            painter.drawText(gutter_rect.adjusted(0,2,-4,-2),
                             Qt.AlignmentFlag.AlignRight|Qt.AlignmentFlag.AlignVCenter,
                             str(ln_text))

        # Separator
        painter.setPen(QColor(p["border"]))
        painter.drawLine(x+self.GUTTER_W, y, x+self.GUTTER_W, y+h)

        # Content
        cx   = x + self.GUTTER_W + 6
        cy   = y + 2
        text = index.data(Qt.ItemDataRole.DisplayRole) or ""
        avail_w = r.width() - cx + r.x() - 4

        # Detect whether the line has the logger's own format:
        # "HH:MM:SS.ms  DIR  content"  or  "DIR  content"
        pos = 0
        has_ts  = len(text) > 14 and text[2]==":" and text[5]==":" and text[8]=="."
        has_dir = False

        # ── Timestamp ─────────────────────────────────────────────────────────
        if has_ts:
            ts_part = text[:13]
            painter.setFont(self._font)
            painter.setPen(QColor(p["ts"]))
            tw = fm.horizontalAdvance(ts_part)
            painter.drawText(cx, cy, tw, h-4, Qt.AlignmentFlag.AlignVCenter, ts_part)
            cx  += tw + fm.horizontalAdvance("  ")
            pos  = 13
            while pos < len(text) and text[pos] == " ": pos += 1

        # ── Direction tag ──────────────────────────────────────────────────────
        dir_part = text[pos:pos+3].strip() if pos < len(text) else ""
        if dir_part in ("TX", "RX", "SYS"):
            has_dir     = True
            dir_color   = {"TX":p["tx"], "RX":p["rx"]}.get(dir_part, p["sys"])
            dir_str     = text[pos:pos+3]
            dw          = self._fm_b.horizontalAdvance(dir_str)
            painter.setFont(self._bold)
            painter.setPen(QColor(dir_color))
            painter.drawText(cx, cy, dw+6, h-4, Qt.AlignmentFlag.AlignVCenter, dir_str)
            cx  += dw + self._fm_b.horizontalAdvance("  ") * 2
            pos += 3
            while pos < len(text) and text[pos] == " ": pos += 1

        # ── Content ────────────────────────────────────────────────────────────
        content = text[pos:] if pos < len(text) else text
        painter.setFont(self._font)
        if has_dir:
            content_color = {"TX":p["tx"], "RX":p["rx"]}.get(dir_part, p["sys"])
        else:
            # Plain file line — no direction tag found, use fg colour
            content_color = p["fg"]
        painter.setPen(QColor(content_color))
        content = fm.elidedText(content, Qt.TextElideMode.ElideRight, avail_w)
        painter.drawText(cx, cy, avail_w, h-4, Qt.AlignmentFlag.AlignVCenter, content)

        painter.restore()


# ─── Log Model (live log — virtual) ───────────────────────────────────────────
class LogModel(QAbstractListModel):
    """
    Qt model backed by LogStore.
    rowCount() and data() are the only methods Qt calls.
    Qt calls data() only for visible rows — O(1) per row, O(visible) total.
    """
    def __init__(self, store:LogStore, show_ts_fn, parent=None):
        super().__init__(parent)
        self._store    = store
        self._show_ts  = show_ts_fn
        # _vis: list of LogStore indices that pass current filter.
        # None = no filter active (show all).
        self._vis      = None
        self._highlight= -1   # highlighted row index

    def rowCount(self, parent=QModelIndex()):
        if self._vis is not None:
            return len(self._vis)
        return len(self._store)

    def data(self, index, role=Qt.ItemDataRole.DisplayRole):
        if not index.isValid(): return None
        row = index.row()
        src = self._vis[row] if self._vis is not None else row
        if src >= len(self._store): return None

        if role == Qt.ItemDataRole.DisplayRole:
            return self._format(src)
        if role == Qt.ItemDataRole.UserRole:
            return src   # master log index (always)
        if role == Qt.ItemDataRole.UserRole+1:
            # Gutter line number:
            # filter active → show position in filtered results (1, 2, 3…)
            # no filter     → show master log line number
            return row + 1 if self._vis is not None else src + 1
        if role == Qt.ItemDataRole.BackgroundRole and src == self._highlight:
            return QColor("#44ef77")
        return None

    def _format(self, src:int) -> str:
        ts   = (self._store.get_ts(src).strftime("%H:%M:%S.%f")[:12]+"  "
                if self._show_ts() else "")
        d    = self._store.get_dir(src).upper().ljust(3)
        text = self._store.get_text(src)
        return f"{ts}{d}  {text}"

    def set_filter_indices(self, indices:list|None):
        self.beginResetModel()
        self._vis = indices
        self.endResetModel()

    def append_rows(self, count:int):
        """Single beginInsertRows/endInsertRows for entire batch — O(1) Qt notifications."""
        if self._vis is not None:
            return   # filter active — worker handles updates
        if count <= 0:
            return
        n = len(self._store)
        self.beginInsertRows(QModelIndex(), n - count, n - 1)
        self.endInsertRows()

    def set_highlight(self, master_idx:int):
        self._highlight = master_idx
        # Find which view row this is
        if self._vis is not None:
            try:    row = self._vis.index(master_idx)
            except: return
        else:
            row = master_idx
        idx = self.index(row)
        self.dataChanged.emit(idx, idx)

    def clear_highlight(self):
        prev = self._highlight; self._highlight = -1
        if prev>=0:
            row = prev if self._vis is None else (
                self._vis.index(prev) if prev in self._vis else -1)
            if row>=0:
                idx=self.index(row); self.dataChanged.emit(idx,idx)

    def total_count(self): return len(self._store)
    def vis_count(self):   return len(self._vis) if self._vis is not None else len(self._store)


# ─── File Model (file viewer — virtual) ───────────────────────────────────────
class FileModel(QAbstractListModel):
    """
    Qt model backed by MmapFileStore.
    data() reads single lines from mmap on demand — file stays on disk.
    """
    def __init__(self, parent=None):
        super().__init__(parent)
        self._store  = None
        self._vis    = None   # list of line indices passing filter, or None=all

    def set_store(self, store:MmapFileStore):
        self.beginResetModel()
        self._store = store
        self._vis   = None
        self.endResetModel()

    def rowCount(self, parent=QModelIndex()):
        if not self._store: return 0
        return len(self._vis) if self._vis is not None else len(self._store)

    def data(self, index, role=Qt.ItemDataRole.DisplayRole):
        if not index.isValid() or not self._store: return None
        row = index.row()
        src = self._vis[row] if self._vis is not None else row
        if src >= len(self._store): return None
        if role == Qt.ItemDataRole.DisplayRole:
            return self._store.get_line(src)
        if role == Qt.ItemDataRole.UserRole+1:
            # Gutter line number:
            # filter active → position in filtered results (1, 2, 3…)
            # no filter     → real file line number
            return row + 1 if self._vis is not None else src + 1
        return None

    def set_filter_indices(self, indices:list|None):
        self.beginResetModel()
        self._vis = indices
        self.endResetModel()

    def total_count(self): return len(self._store) if self._store else 0
    def vis_count(self):
        if not self._store: return 0
        return len(self._vis) if self._vis is not None else len(self._store)


# ─── Workers ──────────────────────────────────────────────────────────────────
class RxWorker(QThread):
    data_ready   = pyqtSignal(bytes)
    disconnected = pyqtSignal()
    def __init__(self,port):
        super().__init__(); self._port=port; self._running=True
    def stop(self): self._running=False
    def run(self):
        while self._running:
            try:
                chunk=self._port.read(4096)
                if chunk: self.data_ready.emit(chunk)
            except serial.SerialException:
                self.disconnected.emit(); break
            except Exception:
                break   # unexpected error — stop cleanly


class LogFilterWorker(QThread):
    """Scans LogStore off UI thread. Emits complete index list when done."""
    result  = pyqtSignal(list)   # complete list of matching indices
    progress= pyqtSignal(int)

    def __init__(self, store:LogStore, filt:str, mode:str, cancel:threading.Event):
        super().__init__()
        self._store=store; self._filt=filt; self._mode=mode; self._cancel=cancel

    def run(self):
        store=self._store; n=len(store); filt=self._filt; mode=self._mode
        cancel=self._cancel; result=[]
        for i in range(n):
            if cancel.is_set(): return
            text=store.get_text(i)
            m=eval_filter(text,filt,mode)
            if (not m) if mode=="hide" else m:
                result.append(i)
            if i%20_000==0 and n>0:
                self.progress.emit(int(i*100/n))
        if not cancel.is_set():
            self.result.emit(result)


class FileIndexWorker(QThread):
    progress= pyqtSignal(int)
    finished= pyqtSignal(int)
    def __init__(self,store,cancel):
        super().__init__(); self._store=store; self._cancel=cancel
    def run(self):
        self._store.build_index(self._cancel,self.progress.emit)
        if not self._cancel.is_set():
            self.finished.emit(len(self._store))


class FileFilterWorker(QThread):
    """Scans MmapFileStore off UI thread. Emits complete index list."""
    result  = pyqtSignal(list)
    progress= pyqtSignal(int)

    def __init__(self,store,filt,mode,cancel):
        super().__init__()
        self._store=store; self._filt=filt; self._mode=mode; self._cancel=cancel

    def run(self):
        store=self._store; n=len(store); filt=self._filt; mode=self._mode
        cancel=self._cancel; result=[]
        for i in range(n):
            if cancel.is_set(): return
            line=store.get_line(i)
            m=eval_filter(line,filt,mode)
            if (not m) if mode=="hide" else m:
                result.append(i)
            if i%20_000==0 and n>0:
                self.progress.emit(int(i*100/n))
        if not cancel.is_set():
            self.result.emit(result)


# ─── Live Log View (QPlainTextEdit — character-selectable) ────────────────────

class LiveLogView(QPlainTextEdit):
    """
    Read-only QPlainTextEdit used for the live serial log.

    Advantages over QListView for this use-case:
      • Native character-level text selection (click-drag, double-click word)
      • Ctrl+C copies selected text including timestamps and direction tags
      • Ctrl+A selects all
      • Scrollbar appears only when needed

    Trade-off: not truly virtual — each line is stored as a QTextBlock.
    In practice this is fine for live logging (millions of short lines stay
    well within Qt's document capacity), and the file viewer retains its
    mmap-backed QListView for O(1) random access on huge files.
    """

    GUTTER_W = 56   # pixels — matches LogDelegate.GUTTER_W

    def __init__(self, palette: dict, font: QFont, parent=None):
        super().__init__(parent)
        self._pal  = palette
        self._font = font
        self._highlight_cursor = None   # for green jump highlight

        self.setReadOnly(True)
        self.setFont(font)
        self.setLineWrapMode(QPlainTextEdit.LineWrapMode.NoWrap)
        self.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self.setUndoRedoEnabled(False)
        self.setMaximumBlockCount(0)   # unlimited

        self._apply_palette()

    # ── Palette / font ────────────────────────────────────────────────────────
    def _apply_palette(self):
        p = self._pal
        self.setStyleSheet(
            f"QPlainTextEdit{{"
            f"  background:{p['bg']};"
            f"  color:{p['fg']};"
            f"  border:none;"
            f"  selection-background-color:{p['border']};"
            f"  selection-color:{p['fg']};"
            f"}}"
        )

    def update_style(self, palette: dict, font: QFont):
        self._pal  = palette
        self._font = font
        self.setFont(font)
        self._apply_palette()
        # Re-render all existing content with new colours
        self._rerender()

    # ── Append a formatted log line ───────────────────────────────────────────
    def append_line(self, formatted_text: str, direction: str):
        """
        Append one formatted log line with syntax colouring.
        direction: 'rx' | 'tx' | 'sys'
        formatted_text: full line as produced by LogModel._format()
        """
        p   = self._pal
        doc = self.document()
        cur = QTextCursor(doc)
        cur.movePosition(QTextCursor.MoveOperation.End)

        if doc.blockCount() > 1 or (doc.blockCount() == 1 and doc.toPlainText()):
            cur.insertText("\n")

        # Parse the formatted line into segments and colour each one.
        # Format: "[HH:MM:SS.ms]  DIR  content"  (timestamp optional)
        text = formatted_text
        pos  = 0

        def _insert(segment: str, colour: str, bold: bool = False):
            fmt = QTextCharFormat()
            fmt.setForeground(QColor(colour))
            if bold:
                f2 = QFont(self._font); f2.setBold(True); fmt.setFont(f2)
            cur.insertText(segment, fmt)

        # ── Timestamp ──────────────────────────────────────────────────────
        has_ts = len(text) > 14 and text[2] == ":" and text[5] == ":" and text[8] == "."
        if has_ts:
            _insert(text[:13], p["ts"])
            _insert("  ", p["ts"])
            pos = 13
            while pos < len(text) and text[pos] == " ":
                pos += 1

        # ── Direction tag ──────────────────────────────────────────────────
        dir_part = text[pos:pos+3].strip() if pos < len(text) else ""
        if dir_part in ("TX", "RX", "SYS"):
            dir_colour = {"TX": p["tx"], "RX": p["rx"]}.get(dir_part, p["sys"])
            _insert(text[pos:pos+3], dir_colour, bold=True)
            _insert("  ", dir_colour)
            pos += 3
            while pos < len(text) and text[pos] == " ":
                pos += 1
            content_colour = dir_colour
        else:
            content_colour = p["fg"]

        # ── Content ────────────────────────────────────────────────────────
        _insert(text[pos:], content_colour)

    # ── Scroll helpers ────────────────────────────────────────────────────────
    def _at_bottom(self) -> bool:
        sb = self.verticalScrollBar()
        return sb.value() >= sb.maximum() - 4   # 4px tolerance

    def scroll_to_bottom(self):
        self.moveCursor(QTextCursor.MoveOperation.End)
        self.ensureCursorVisible()

    def scroll_to_row(self, row: int):
        """Scroll so that block `row` is centred in the viewport."""
        doc   = self.document()
        block = doc.findBlockByNumber(row)
        if not block.isValid():
            return
        cur = QTextCursor(block)
        self.setTextCursor(cur)
        self.centerCursor()

    # ── Jump highlight (green, 3-second fade) ─────────────────────────────────
    def highlight_row(self, row: int):
        """Paint block `row` with the green jump highlight."""
        doc   = self.document()
        block = doc.findBlockByNumber(row)
        if not block.isValid():
            return
        sel = QTextEdit.ExtraSelection()
        fmt = QTextCharFormat()
        fmt.setBackground(QColor(self._pal.get("green", "#44ef77")))
        fmt.setForeground(QColor(self._pal["bg"]))
        sel.format  = fmt
        cur = QTextCursor(block)
        cur.select(QTextCursor.SelectionType.LineUnderCursor)
        sel.cursor  = cur
        self.setExtraSelections([sel])
        self._highlight_cursor = cur

    def clear_highlight(self):
        self.setExtraSelections([])
        self._highlight_cursor = None

    # ── Full re-render (theme change) ─────────────────────────────────────────
    def _rerender(self):
        """
        Called after a theme or font change.
        Iterates every QTextBlock and re-colours its char-formats.
        For very large logs this is O(n) but theme changes are infrequent.
        """
        doc   = self.document()
        block = doc.begin()
        p     = self._pal
        while block.isValid():
            text = block.text()
            pos  = 0
            cur  = QTextCursor(block)
            cur.select(QTextCursor.SelectionType.BlockUnderCursor)

            # Determine direction colour from the line content
            has_ts = len(text) > 14 and text[2]==":" and text[5]==":" and text[8]=="."
            if has_ts:
                pos = 13
                while pos < len(text) and text[pos] == " ":
                    pos += 1
            dir_part = text[pos:pos+3].strip() if pos < len(text) else ""
            if dir_part in ("TX","RX","SYS"):
                dir_colour = {"TX":p["tx"],"RX":p["rx"]}.get(dir_part, p["sys"])
            else:
                dir_colour = p["fg"]

            # Re-apply a uniform colour to the whole block (good enough for
            # re-theme; the fine-grained split only happens on insert).
            fmt = QTextCharFormat()
            fmt.setForeground(QColor(dir_colour))
            cur.setCharFormat(fmt)
            block = block.next()

    # ── Clear ─────────────────────────────────────────────────────────────────
    def clear_log(self):
        self.clear()

    # ── Context menu: always include Copy ─────────────────────────────────────
    def contextMenuEvent(self, event):
        menu = self.createStandardContextMenu()
        menu.exec(event.globalPos())


# ─── Log View widget (QListView — used for File Viewer only) ──────────────────
class LogView(QListView):
    """
    QListView with our custom delegate.
    Only visible rows are ever painted — true virtual rendering.
    Used exclusively for the File View tab (mmap-backed large file display).
    """
    def __init__(self, model:QAbstractListModel, palette:dict, font:QFont,
                 file_mode:bool=False, parent=None):
        super().__init__(parent)
        self._pal      = palette
        self._font     = font
        self._delegate = LogDelegate(palette, font, file_mode=file_mode)
        self.setModel(model)
        self.setItemDelegate(self._delegate)
        self.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self.setVerticalScrollMode(QAbstractItemView.ScrollMode.ScrollPerPixel)
        self.setUniformItemSizes(True)   # critical for performance
        self.setSelectionMode(QAbstractItemView.SelectionMode.SingleSelection)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self._apply_palette()

    def _apply_palette(self):
        p=self._pal
        self.setStyleSheet(
            f"QListView{{background:{p['bg']};color:{p['fg']};border:none;"
            f"outline:0;selection-background-color:{p['border']};}}")

    def update_style(self, palette:dict, font:QFont):
        self._pal=palette; self._font=font
        self._delegate.update_style(palette,font)
        self._apply_palette()
        self.reset()

    def scroll_to_bottom(self):
        m=self.model()
        if m and m.rowCount()>0:
            self.scrollTo(m.index(m.rowCount()-1))

    def scroll_to_row(self, row:int):
        m=self.model()
        if m and 0<=row<m.rowCount():
            idx=m.index(row)
            self.scrollTo(idx, QAbstractItemView.ScrollHint.PositionAtCenter)
            self.setCurrentIndex(idx)


# ─── Palette Editor ───────────────────────────────────────────────────────────
class PaletteEditor(QDialog):
    def __init__(self, parent, palette, on_apply):
        super().__init__(parent); self.setWindowTitle("Colour Palette Editor")
        self.setModal(True); self._pal=dict(palette); self._on_apply=on_apply
        self._sw={}; p=palette
        self.setStyleSheet(f"background:{p['bg2']};color:{p['fg']};")
        main=QVBoxLayout(self); main.setContentsMargins(16,16,16,12)
        t=QLabel("Colour Palette Editor")
        t.setStyleSheet(f"font-weight:bold;font-size:13px;"); main.addWidget(t)
        gw=QWidget(); gl=QHBoxLayout(gw); nl=QVBoxLayout(); sl=QVBoxLayout(); el=QVBoxLayout()
        for key,label in THEME_KEYS:
            c=self._pal.get(key,"#888888"); nl.addWidget(QLabel(label))
            sw=QPushButton(); sw.setFixedSize(28,22)
            sw.setStyleSheet(f"background:{c};border:1px solid #888;")
            sw.clicked.connect(lambda _,k=key:self._pick(k))
            sl.addWidget(sw); self._sw[key]=sw
            en=QLineEdit(c); en.setFixedWidth(90)
            en.setStyleSheet("background:#fff;color:#000;border:1px solid #aaa;padding:1px 4px;")
            en.textChanged.connect(lambda v,k=key:self._ot(k,v)); el.addWidget(en)
        gl.addLayout(nl); gl.addLayout(sl); gl.addLayout(el); main.addWidget(gw)
        pr=QHBoxLayout(); pr.addWidget(QLabel("Preset:"))
        self._pcb=QComboBox(); self._pcb.addItems([k for k in THEMES if k!="Custom"])
        pr.addWidget(self._pcb); lb=QPushButton("Load"); lb.clicked.connect(self._load)
        pr.addWidget(lb); pr.addStretch(); main.addLayout(pr)
        br=QHBoxLayout()
        ab=QPushButton("Apply & Save as Custom")
        ab.setStyleSheet("background:#1255a8;color:#fff;padding:4px 12px;border:none;border-radius:3px;")
        ab.clicked.connect(self._apply)
        cb=QPushButton("Cancel"); cb.clicked.connect(self.reject)
        br.addWidget(ab); br.addStretch(); br.addWidget(cb); main.addLayout(br)

    def _pick(self,key):
        from PyQt6.QtWidgets import QColorDialog
        c=QColorDialog.getColor(QColor(self._pal.get(key,"#fff")),self)
        if c.isValid():
            self._pal[key]=c.name()
            self._sw[key].setStyleSheet(f"background:{c.name()};border:1px solid #888;")

    def _ot(self,key,val):
        val=val.strip()
        if len(val)==7 and val.startswith("#"):
            try:
                int(val[1:],16); self._pal[key]=val
                self._sw[key].setStyleSheet(f"background:{val};border:1px solid #888;")
            except ValueError: pass

    def _load(self):
        p=THEMES.get(self._pcb.currentText(),{})
        for k,v in p.items():
            if k in self._sw:
                self._pal[k]=v; self._sw[k].setStyleSheet(f"background:{v};border:1px solid #888;")

    def _apply(self): self._on_apply(dict(self._pal)); self.accept()


# ─── About Window ─────────────────────────────────────────────────────────────
class AboutWindow(QDialog):
    def __init__(self,parent,palette):
        super().__init__(parent); self.setWindowTitle(f"BluOwl SerialMonitor v{APP_VERSION}")
        self.setModal(True); self.resize(520,460); p=palette
        self.setStyleSheet(f"background:{p['bg2']};color:{p['fg']};")
