    def _make_search_bar(self, view:LogView) -> QWidget:
        sb=QWidget(); sb.setVisible(False)
        lay=QHBoxLayout(sb); lay.setContentsMargins(6,3,6,3); lay.setSpacing(5)
        en=QLineEdit(); en.setPlaceholderText("Find…"); en.setFixedHeight(24)
        inf=QLabel("")
        pb=QPushButton("▲"); pb.setFixedWidth(26)
        nb=QPushButton("▼"); nb.setFixedWidth(26)
        xb=QPushButton("✕"); xb.setFixedWidth(26)
        def _find(fwd=True):
            t=en.text()
            if not t: return
            model=view.model(); n=model.rowCount()
            cur=view.currentIndex(); start=cur.row() if cur.isValid() else -1
            rng=range(start+1,n) if fwd else range(start-1,-1,-1)
            for r in rng:
                txt=model.data(model.index(r),Qt.ItemDataRole.DisplayRole) or ""
                if t.lower() in txt.lower():
                    view.scroll_to_row(r); inf.setText(f"row {r+1}"); return
            # wrap
            rng2=range(0,start+1) if fwd else range(n-1,start-1,-1)
            for r in rng2:
                txt=model.data(model.index(r),Qt.ItemDataRole.DisplayRole) or ""
                if t.lower() in txt.lower():
                    view.scroll_to_row(r); inf.setText(f"row {r+1} (wrapped)"); return
            inf.setText("not found")
        en.returnPressed.connect(lambda:_find(True))
        pb.clicked.connect(lambda:_find(False)); nb.clicked.connect(lambda:_find(True))
        xb.clicked.connect(lambda:sb.setVisible(False))
        lay.addWidget(QLabel("Find:")); lay.addWidget(en)
        lay.addWidget(pb); lay.addWidget(nb); lay.addWidget(inf)
        lay.addStretch(); lay.addWidget(xb)
        sb._entry=en
        return sb

    def _make_search_bar_plain(self, view: "LiveLogView") -> QWidget:
        """Search bar variant for QPlainTextEdit (live view)."""
        sb=QWidget(); sb.setVisible(False)
        lay=QHBoxLayout(sb); lay.setContentsMargins(6,3,6,3); lay.setSpacing(5)
        en=QLineEdit(); en.setPlaceholderText("Find…"); en.setFixedHeight(24)
        inf=QLabel("")
        pb=QPushButton("▲"); pb.setFixedWidth(26)
        nb=QPushButton("▼"); nb.setFixedWidth(26)
        xb=QPushButton("✕"); xb.setFixedWidth(26)
        def _find(fwd=True):
            t=en.text()
            if not t: inf.setText(""); return
            flags = QTextDocument.FindFlag(0)
            if not fwd:
                flags = QTextDocument.FindFlag.FindBackward
            found = view.find(t, flags)
            if not found:
                # wrap around
                cur = view.textCursor()
                if fwd:
                    view.moveCursor(QTextCursor.MoveOperation.Start)
                else:
                    view.moveCursor(QTextCursor.MoveOperation.End)
                found = view.find(t, flags)
            inf.setText("not found" if not found else "")
        en.returnPressed.connect(lambda:_find(True))
        pb.clicked.connect(lambda:_find(False)); nb.clicked.connect(lambda:_find(True))
        xb.clicked.connect(lambda:sb.setVisible(False))
        lay.addWidget(QLabel("Find:")); lay.addWidget(en)
        lay.addWidget(pb); lay.addWidget(nb); lay.addWidget(inf)
        lay.addStretch(); lay.addWidget(xb)
        sb._entry=en
        return sb

    def _show_search(self, live:bool):
        sb=self._live_sb if live else self._file_sb
        sb.setVisible(True); sb._entry.setFocus(); sb._entry.selectAll()

