    app=QApplication(sys.argv)
    app.setStyle("Fusion")
    _icon=_get_icon()
    app.setWindowIcon(_icon)          # taskbar + alt-tab
    w=BluOwlSerialMonitor()
    w.setWindowIcon(_icon)            # title bar
    w.show()
    sys.exit(app.exec())
